# between two steps, i.e., after the draft model and before the
# next target model. We don't need any sync in between the target
# model and draft model, or between different steps of spec, anymore."

    def _sync_for_spec_decode(self, mode, step_type):
        """Synchronize NPU stream for speculative decoding."""
        if mode == FULL:
            if step_type == "after_target":
                # target model 和 draft model 之间的同步 - 不必要
                torch.npu.current_stream().synchronize()
            elif step_type == "between_spec_steps":
                # 不同 spec 步骤之间的同步 - 不必要
                torch.npu.current_stream().synchronize()
            elif step_type == "after_draft":
                # draft model 完成后、下一个 target model 之前 - 必要
                torch.npu.current_stream().synchronize()

    def _replay_graph(self, graph, mode):
        """Replay a captured ACL graph."""
        if mode == FULL:
            # 多处冗余同步导致异步调度 hang
            torch.npu.current_stream().synchronize()
            graph.replay()
            torch.npu.current_stream().synchronize()
        return graph
